            check(NaturalWaterSources.problem(machine,X,Y-2,0)==null,"native water exactly eight metres away is available");check(NaturalWaterSources.problem(machine,X,Y-3,0)!=null&&NaturalWaterSources.problem(machine,X,Y-2,-1)!=null,"source selection rejects range and layer mismatches");
            List<NaturalWaterSources.Source> sources=NaturalWaterSources.nearby(machine);check(sources.stream().anyMatch(s->s.x==X&&s.y==Y-2&&s.layer==0),"bounded explicit source lookup captures native coordinates");
            Path folder=Paths.get(com.wurmonline.server.ServerDirInfo.getFileDBPath()).resolve("native-steam-water-pumps");Files.createDirectories(folder);Path file=folder.resolve("pumps.properties");RailwayPumpController controller=new RailwayPumpController(file,100);
