            water.setWeight(IndustrialWaterTankRegistry.MAX_WEIGHT_GRAMS,true);controller.tick(1);check(controller.state().get(machine.getWurmId()).running&&controller.state().get(machine.getWurmId()).status.contains("full"),"a full tank pauses with clear status while retaining automatic intent");controller.tick(30);check(water.getWeightGrams()==IndustrialWaterTankRegistry.MAX_WEIGHT_GRAMS,"backpressure cannot generate overflow or bank instant water");water.setWeight(IndustrialWaterTankRegistry.MAX_WEIGHT_GRAMS-50000,true);controller.tick(1);check(water.getWeightGrams()==IndustrialWaterTankRegistry.MAX_WEIGHT_GRAMS,"freed half-interval capacity automatically fills only its remaining50L");
            water.setWeight(100000,true);controller=new RailwayPumpController(file,100);controller.tick(0);controller.tick(.99);check(water.getWeightGrams()==100000,"restart retains power intent but no offline/earlier transfer allowance");controller.tick(.01);check(water.getWeightGrams()==200000,"freshly earned interval resumes native production after restart");
            controller.stop(owner,machine.getWurmId());controller.tick(60);check(water.getWeightGrams()==200000&&!controller.state().get(machine.getWurmId()).running,"manualSTOP prevents production and stays saved off");
            access(controller,owner,other,machine,tank);
            controller.start(owner,machine.getWurmId());tank.setLastOwnerId(other.getWurmId());controller.tick(1);check(water.getWeightGrams()==200000&&controller.state().get(machine.getWurmId()).status.contains("same owner"),"changed tank ownership pauses before creating water");tank.setLastOwnerId(owner.getWurmId());controller.tick(1);check(water.getWeightGrams()==300000,"restored authorized storage automatically resumes without operator touring pumps");
            int oldSource=Server.surfaceMesh.getTile(X,Y-2);Server.surfaceMesh.setTile(X,Y-2,Tiles.encode((short)-20,Tiles.Tile.TILE_LAVA.id,(byte)0));controller.tick(1);check(water.getWeightGrams()==300000&&controller.state().get(machine.getWurmId()).status.contains("Lava"),"changed lava/tar source halts generation with an explicit reason");Server.surfaceMesh.setTile(X,Y-2,oldSource);controller.tick(1);check(water.getWeightGrams()==400000,"restored native source resumes at configured rate");controller.stop(owner,machine.getWurmId());
            nativeFaults(owner,machine,tank,water);salinity(owner,machine,tank,types);
