    private static void access(RailwayPumpController controller,Player owner,Player other,Item machine,Item tank)throws Exception {check(!controller.snapshot(other,machine.getWurmId()).canControl,"another ordinary player can inspect but not control the pump");denied(()->controller.start(other,machine.getWurmId()),"another player cannot start by forged direct interaction");RailwaySteamWaterPump.View current=controller.snapshot(owner,machine.getWurmId());RailwaySteamWaterPump.Request stale=RailwaySteamWaterPump.fromAnswers(current,answers(current,tank.getWurmId(),"save"));controller.start(owner,machine.getWurmId());controller.stop(owner,machine.getWurmId());denied(()->controller.apply(owner,machine.getWurmId(),stale),"stale captured settings cannot overwrite a newerSTOP");owner.getStatus().getPosition().setPosX((X+3)*4+2);denied(()->controller.start(owner,machine.getWurmId()),"controls recheck actual owner distance");owner.getStatus().getPosition().setPosX(X*4+2);check(MachineWaterSources.storageProblem(machine.getPosX(),machine.getPosY(),0,tank,owner.getWurmId(),16)==null,"actual tank within16m remains eligible");float before=tank.getPosX();tank.setPosXYZ((X+5)*4+2,tank.getPosY(),tank.getPosZ());check(MachineWaterSources.storageProblem(machine.getPosX(),machine.getPosY(),0,tank,owner.getWurmId(),16)!=null,"moved storage outside16m cannot receive water");tank.setPosXYZ(before,tank.getPosY(),tank.getPosZ());}
    private static void nativeFaults(Player owner,Item machine,Item tank,Item original)throws Exception {
        tank.dropItem(original.getWurmId(),false);Items.destroyItem(original.getWurmId());int count=countWater();insertTarget=tank.getWurmId();insertMode=1;
        LiquidTankTransfers.Result refused=NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false);check(refused.transferredMillilitres==0&&!refused.requiresOperatorIntervention&&tank.getItems().isEmpty()&&countWater()==count&&!Items.getItemOptional(rejectedId).isPresent(),"refused native insertion cleans up unearned water without dropping, duplicating or orphaning items");
        LiquidTankTransfers.Result first=NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false);Item water=LiquidTankPolicy.contents(tank);made.add(water);check(first.transferredMillilitres==1000&&water.getWeightGrams()==1000,"normal retry creates exactly its earned allowance");growthTarget=water.getWurmId();growthMode=1;
        LiquidTankTransfers.Result blocked=NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false);check(blocked.requiresOperatorIntervention&&blocked.transferredMillilitres==0&&water.getWeightGrams()==1000&&LiquidTankTransfers.isFaulted(tank),"unexpected native growth refusal conserves water and durably quarantines storage");
        check(new DbItem(tank.getWurmId()).getAuxData()==99&&NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false).transferredMillilitres==0,"persistent recovery flag blocks future production, including retry");tank.dropItem(water.getWurmId(),false);Items.destroyItem(water.getWurmId());owner.getStatus().getPosition().setPosX(tank.getPosX());LiquidTankTransfers.clearFault(owner,tank);owner.getStatus().getPosition().setPosX(X*4+2);
        NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false);water=LiquidTankPolicy.contents(tank);made.add(water);growthTarget=water.getWurmId();growthMode=2;
        LiquidTankTransfers.Result committed=NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false);check(committed.requiresOperatorIntervention&&committed.transferredMillilitres==1000&&water.getWeightGrams()==2000&&LiquidTankTransfers.isFaulted(tank),"notification failure after native commit reports exactly addedwater once and stops for recovery");check(NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false).transferredMillilitres==0&&water.getWeightGrams()==2000,"postcommit retries never duplicate alreadycommitted production");tank.dropItem(water.getWurmId(),false);Items.destroyItem(water.getWurmId());owner.getStatus().getPosition().setPosX(tank.getPosX());LiquidTankTransfers.clearFault(owner,tank);owner.getStatus().getPosition().setPosX(X*4+2);
    }
    private static void salinity(Player owner,Item machine,Item tank,byte[][] types)throws Exception {types[X][Y-2]=WaterType.SEA;boolean salted=NaturalWaterSources.salted(X,Y-2,0);check(salted,"native sea-water identity is detected");NaturalWaterProduction.add(tank,owner.getWurmId(),2000,salted);Item water=LiquidTankPolicy.contents(tank);made.add(water);check(water.isSalted()&&water.getWeightGrams()==2000,"natural sea water retains its salted property in real storage");types[X][Y-2]=WaterType.LAKE;check(NaturalWaterProduction.add(tank,owner.getWurmId(),1000,false).transferredMillilitres==0&&water.getWeightGrams()==2000&&water.isSalted(),"production never mixes fresh and salty water or changes existing water identity");Item car=placed(RailwayTankCar.templateId,X+1,Y,owner.getWurmId());check(NaturalWaterProduction.add(car,owner.getWurmId(),1000,true).transferredMillilitres==0&&car.getItems().isEmpty(),"natural-water production cannot target railway Tank Cars directly");}
    private static void startThroughQuestion(final RailwayPumpController controller,final Player owner,Item machine,Item tank)throws Exception {final int[] submitted={0};RailwaySteamWaterPump.Api api=new RailwaySteamWaterPump.Api(){public RailwaySteamWaterPump.View snapshot(Creature a,long id){return controller.snapshot(a,id);}public void submit(Creature a,long id,RailwaySteamWaterPump.Request r){submitted[0]++;try{controller.apply(a,id,r);}catch(Exception failure){throw new IllegalStateException(failure);}}public void interact(Creature a,long id,RailwaySteamWaterPump.Interaction mode){throw new AssertionError("unexpected interaction");}};RailwaySteamWaterPump.View view=controller.snapshot(owner,machine.getWurmId());RailwaySteamWaterPump.show(owner,machine.getWurmId(),api);Question question=latestQuestion(owner);Properties answer=answers(view,tank.getWurmId(),"start");question.answer(answer);question.answer(answer);check(submitted[0]==1,"actual ModQuestionImpl answer replay cannot start or save twice");}
    private static Properties answers(RailwaySteamWaterPump.View view,long tank,String action){Properties p=new Properties();p.setProperty(action,"true");int chosen=0;for(int i=0;i<view.tanks.size();i++)if(view.tanks.get(i).id==tank)chosen=i+1;if(chosen==0)throw new AssertionError("owned tank missing from source choices");p.setProperty("tank_choice",Integer.toString(chosen));chosen=0;for(int i=0;i<view.sources.size();i++){RailwaySteamWaterPump.SourceChoice source=view.sources.get(i);if(source.x==X&&source.y==Y-2&&source.layer==0)chosen=i+1;}if(chosen==0)throw new AssertionError("native water missing from source choices");p.setProperty("source_choice",Integer.toString(chosen));return p;}
    private static void waterTile(int x,int y){for(int dx=0;dx<=1;dx++)for(int dy=0;dy<=1;dy++)Server.surfaceMesh.setTile(x+dx,y+dy,Tiles.encode((short)-20,Tiles.Tile.TILE_DIRT.id,(byte)0));}
    private static int countWater(){int count=0;for(Item item:Items.getAllItems())if(item.getTemplateId()==ItemList.water)count++;return count;}
    private static Item placed(int template,int x,int y,long owner)throws Exception{Item item=ItemFactory.createItem(template,65f,x*4+2f,y*4+2f,0,true,(byte)0,NO_ID,"Steam Water Pump native fixture");item.setLastOwnerId(owner);made.add(item);return item;}
    private static Player player(long id)throws Exception{Method create=PassengerWorldSmoke.class.getDeclaredMethod("player",long.class,float.class,float.class);create.setAccessible(true);Player p=(Player)create.invoke(null,id,X*4+2f,Y*4+2f);Field power=PlayerInfo.class.getDeclaredField("power");power.setAccessible(true);power.setByte(p.getSaveFile(),(byte)0);p.getStatus().setLayer(0);p.getStatus().getPosition().setPosZ(5f,false);p.currentTile=Zones.getOrCreateTile(X,Y,true);return p;}
    private static void removePlayer(Player p)throws Exception{Method remove=PassengerWorldSmoke.class.getDeclaredMethod("removePlayer",Player.class);remove.setAccessible(true);remove.invoke(null,p);}
    @SuppressWarnings("unchecked") private static Question latestQuestion(Creature actor)throws Exception{Field field=Questions.class.getDeclaredField("questions");field.setAccessible(true);Question latest=null;for(Question q:((Map<Integer,Question>)field.get(null)).values())if(q.getResponder()==actor&&(latest==null||q.getId()>latest.getId()))latest=q;if(latest==null)throw new AssertionError("native pump question absent");return latest;}
    private interface Work{void run()throws Exception;}private static void denied(Work work,String message)throws Exception{boolean denied=false;try{work.run();}catch(IllegalArgumentException expected){denied=true;}check(denied,message);}
    private static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
